//! Immutable native Box3D hull images, generated by diagnostics/box3d-parity/hull-build.c.
use serde_json::Value;
use shallot_physics::hull_build::*;
use shallot_physics::math::{Quat, Transform, Vec3};

#[test]
fn construction_and_generators_match_native_images() {
    let cases: Value = serde_json::from_str(include_str!("hull_build.gold.json")).unwrap();
    for case in cases.as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let args: Vec<f32> = case["args"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| f32::from_bits(v.as_u64().unwrap() as u32))
            .collect();
        let v = |i: usize| Vec3::new(args[i], args[i + 1], args[i + 2]);
        let got = match case["operation"].as_u64().unwrap() {
            0 => {
                let points: Vec<_> = case["points"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| {
                        let f = |i: usize| f32::from_bits(p[i].as_u64().unwrap() as u32);
                        Vec3::new(f(0), f(1), f(2))
                    })
                    .collect();
                create_hull(&points, case["budget"].as_i64().unwrap() as i32)
            }
            1 => create_cylinder(args[0], args[1], args[2], args[3] as usize),
            2 => create_cone(args[0], args[1], args[2], args[3] as usize),
            3 => create_rock(args[0]),
            4 => Some(make_transformed_box(
                args[0],
                args[1],
                args[2],
                Transform::IDENTITY,
            )),
            5 => Some(make_transformed_box(
                args[0],
                args[0],
                args[0],
                Transform::IDENTITY,
            )),
            6 => Some(make_transformed_box(
                args[0],
                args[1],
                args[2],
                Transform {
                    p: v(3),
                    q: Quat::IDENTITY,
                },
            )),
            7 => Some(make_transformed_box(
                args[0],
                args[1],
                args[2],
                Transform {
                    p: v(3),
                    q: Quat {
                        v: v(6),
                        s: args[9],
                    },
                },
            )),
            _ => unreachable!(),
        };
        if case["words"].is_null() {
            assert!(got.is_none(), "{name}: expected null");
            continue;
        }
        let got = got.unwrap_or_else(|| panic!("{name}: unexpected null"));
        let words = case["words"].as_array().unwrap();
        assert_eq!(got.bytes().len(), words.len() * 4, "{name}: byte count");
        for hash_pass in [false, true] {
            for (i, (bytes, want)) in got.bytes().as_chunks::<4>().0.iter().zip(words).enumerate() {
                if (i == 2 || i == 3) != hash_pass {
                    continue;
                }
                assert_eq!(
                    u32::from_le_bytes(*bytes),
                    want.as_u64().unwrap() as u32,
                    "{name}: word {i}"
                );
            }
        }
    }
}
